recap:
O **vermelho** é o teste que falhou, e o **verde**, o que passou. `Expected` é o gabarito, e `Received` é a resposta da função. Leia os dois e decida quem errou.

```javascript
test('o dobro de 4 é 8', () => {
  expect(dobro(4)).toBe(8);
});
// × o dobro de 4 é 8
//   Expected: 8 | Received: 6
```

exercises.starter:
// corrija o erro nesta função
function totalDeOvos(duzias) {
  return duzias + 12;
}

test('3 dúzias são 36 ovos', () => {
  expect(totalDeOvos(3)).toBe(36);
});

exercises.solution:
function totalDeOvos(duzias) {
  return duzias * 12;
}

test('3 dúzias são 36 ovos', () => {
  expect(totalDeOvos(3)).toBe(36);
});

exercises.starter:
// corrija o erro nesta função
function calcularDesconto(centavos, percentual) {
  return centavos * percentual / 100;
}

test('10% de 1000 centavos são 100', () => {
  expect(calcularDesconto(1000, 10)).toBe(100);
});

test('10% de 1255 centavos arredonda para 126', () => {
  expect(calcularDesconto(1255, 10)).toBe(126);
});

exercises.solution:
function calcularDesconto(centavos, percentual) {
  return Math.round(centavos * percentual / 100);
}

test('10% de 1000 centavos são 100', () => {
  expect(calcularDesconto(1000, 10)).toBe(100);
});

test('10% de 1255 centavos arredonda para 126', () => {
  expect(calcularDesconto(1255, 10)).toBe(126);
});

exercises.starter:
// corrija o erro destas duas funções
function calcularMedia(prova, trabalho) {
  return prova + trabalho / 2;
}

function fraseDoBoletim(aluno, nota) {
  console.log(`${aluno} tirou ${nota}`);
}

test('a média de 8 e 6 é 7', () => {
  expect(calcularMedia(8, 6)).toBe(7);
});

test('a frase do boletim traz o nome e a nota', () => {
  expect(fraseDoBoletim('Ana', 7)).toBe('Ana tirou 7');
});

exercises.solution:
function calcularMedia(prova, trabalho) {
  return (prova + trabalho) / 2;
}

function fraseDoBoletim(aluno, nota) {
  return `${aluno} tirou ${nota}`;
}

test('a média de 8 e 6 é 7', () => {
  expect(calcularMedia(8, 6)).toBe(7);
});

test('a frase do boletim traz o nome e a nota', () => {
  expect(fraseDoBoletim('Ana', 7)).toBe('Ana tirou 7');
});
